package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.BlockGetter;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.block.state.StateDefinition;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;
/** Measures local combined brightness, including artificial light, as 0..15 Redstone. */
public class EngineeringLightSensorBlock extends Block{public static final IntegerProperty POWER=IntegerProperty.create("power",0,15);public EngineeringLightSensorBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(POWER,0));}@Override public MapCodec<EngineeringLightSensorBlock> codec(){return RedstoneEngineering.ENGINEERING_LIGHT_SENSOR_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(POWER);}@Override protected boolean isSignalSource(BlockState s){return true;}@Override protected int getSignal(BlockState s,BlockGetter l,BlockPos p,Direction d){return s.getValue(POWER);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(!l.isClientSide)l.scheduleTick(p,this,1);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int v=Math.max(0,Math.min(15,l.getMaxLocalRawBrightness(p.above())));if(v!=s.getValue(POWER)){l.setBlock(p,s.setValue(POWER,v),Block.UPDATE_CLIENTS);l.updateNeighborsAt(p,this);}l.scheduleTick(p,this,10);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Local Light Sensor = "+s.getValue(POWER)+"/15"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
